/// <summary>
/// Eventhandler class for <c>InventTable</c>
/// </summary>
internal final class METInventTableEventHandler
{
}

Method.Source:
    /// <summary>
    /// Event handler for post insert logic
    /// </summary>
    /// <param name="sender">InventTable buffer</param>
    /// <param name="e">Arguments</param>
    [DataEventHandler(tableStr(InventTable), DataEventType::Inserted),
    SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void InventTable_onInserted(Common sender, DataEventArgs e)
    {
        InventTable insertedInventTable = sender as InventTable;
        insertedInventTable.metInsertMETInventTable();

        if(GUPParameters::find().METPriceChangeTrackingEnable)
        {
            METPriceChangeEventProduct::metProcessTrackChange(insertedInventTable);
        }
    }

/// <summary>
/// Event handler for post update logic
/// </summary>
/// <param name="sender">InventTable buffer</param>
/// <param name="e">Arguments</param>
[DataEventHandler(tableStr(InventTable), DataEventType::Updated),
SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
public static void InventTable_onUpdated(Common sender, DataEventArgs e)
{
    InventTable updatedInventTable = sender as InventTable;
    updatedInventTable.metInsertMETInventTable();
}
